"""FROZEN reference: the pre-merge ``stripe_update_*`` bodies from git HEAD.

Generated by ``.pi/gen_stage2_fixture.py`` from
``git show HEAD:services/protocol-payment/ideal/ideal_qr_extract.py`` (commit
e352db6) before stage 2 moved these two writers into
``common/stripe_flow.py``. The bodies were byte-identical in ideal / twint /
blik, so one copy represents all three.

**Do not edit this file.** It is the "before" side of the differential test in
``tests/governance/test_stage2_replay_selfcheck.py``; editing it turns that test
into a comparison of the new code against itself.

The only transformation applied to the captured source is dependency injection:
every ambient name the body closed over is now an attribute of ``Seams``, which
the test fills from the extractor under test. No statement, literal or
expression was rewritten.

It deliberately does not import ``common``: that package only resolves after the
child-process ``sys.path`` setup, and pyright reports it as ``reportMissingImports``
from ``tests/``. The pre-existing test files carry a frozen baseline row for
exactly that finding; a new file is allowed no such row, so the two values
(``stripe_payment_pages``, ``timeout``) are injected instead.
"""

from __future__ import annotations

from typing import Any

import requests


class Seams:
    """The per-extractor values and callables the pre-merge bodies closed over."""

    def __init__(
        self,
        *,
        dump_http,
        log,
        saved_payment_value,
        checkout_not_active,
        stripe_version: str,
        stripe_payment_pages: str,
        timeout: float,
    ) -> None:
        self.dump_http = dump_http
        self.log = log
        self.saved_payment_value = saved_payment_value
        self.checkout_not_active = checkout_not_active
        self.stripe_version = stripe_version
        self.stripe_payment_pages = stripe_payment_pages
        self.timeout = timeout


def stripe_update_customer_data(
    stripe: requests.Session,
    cs_id: str,
    stripe_pk: str,
    ctx: dict[str, Any],
    billing: dict[str, str],
    *,
    seams: Seams,
) -> bool:
    body: dict[str, Any] = {
        "key": stripe_pk,
        "_stripe_version": seams.stripe_version,
        "expected_amount": str(ctx.get("checkout_amount") or 0),
        "elements_session_client[session_id]": ctx["elements_session_id"],
        "elements_session_client[stripe_js_id]": ctx["stripe_js_id"],
        "elements_session_client[referrer_host]": "chatgpt.com",
        "elements_session_client[elements_init_source]": "custom_checkout",
        "elements_session_client[locale]": ctx["locale"],
        "elements_session_client[client_betas][0]": "custom_checkout_server_updates_1",
        "elements_session_client[client_betas][1]": "custom_checkout_manual_approval_1",
        "customer_data[email]": billing["email"],
        "customer_data[name]": billing["name"],
        "customer_data[address][country]": billing["country"],
        "customer_data[address][line1]": billing["line1"],
        "customer_data[address][city]": billing["city"],
        "customer_data[address][postal_code]": billing["postal_code"],
    }
    if billing.get("line2"):
        body["customer_data[address][line2]"] = billing["line2"]
    if billing.get("state"):
        body["customer_data[address][state]"] = billing["state"]

    url = f"{seams.stripe_payment_pages}/{cs_id}"
    try:
        resp = stripe.post(url, data=body, timeout=seams.timeout)
        seams.dump_http(resp, "customer_data_update_nl", body, "POST", url, force=resp.status_code >= 400)
        if resp.status_code < 400:
            seams.log(f"荷兰 customer_data 已提交: {billing['name']} / {billing['city']} / {billing['postal_code']}")
            return True
        if seams.checkout_not_active(resp.text):
            raise RuntimeError("checkout_not_active_session")
        seams.log(f"荷兰 customer_data 提交失败 HTTP {resp.status_code}: {resp.text[:180]}", "[WARN] ")
    except Exception as exc:
        if seams.checkout_not_active(exc):
            raise
        seams.log(f"荷兰 customer_data 提交异常: {exc}", "[WARN] ")
    return False


def stripe_update_tax_region(
    stripe: requests.Session,
    cs_id: str,
    stripe_pk: str,
    ctx: dict[str, Any],
    billing: dict[str, str],
    *,
    seams: Seams,
) -> bool:
    body: dict[str, Any] = {
        "key": stripe_pk,
        "_stripe_version": seams.stripe_version,
        "elements_session_client[session_id]": ctx["elements_session_id"],
        "elements_session_client[stripe_js_id]": ctx["stripe_js_id"],
        "elements_session_client[referrer_host]": "chatgpt.com",
        "elements_session_client[elements_init_source]": "custom_checkout",
        "elements_session_client[is_aggregation_expected]": "false",
        "elements_session_client[locale]": ctx["locale"],
        "elements_session_client[client_betas][0]": "custom_checkout_server_updates_1",
        "elements_session_client[client_betas][1]": "custom_checkout_manual_approval_1",
        "elements_options_client[saved_payment_method][enable_save]": seams.saved_payment_value(),
        "elements_options_client[saved_payment_method][enable_redisplay]": seams.saved_payment_value(),
        "client_attribution_metadata[merchant_integration_additional_elements][0]": "expressCheckout",
        "client_attribution_metadata[merchant_integration_additional_elements][1]": "payment",
        "client_attribution_metadata[merchant_integration_additional_elements][2]": "address",
        "tax_region[country]": billing["country"],
        "tax_region[postal_code]": billing["postal_code"],
        "tax_region[line1]": billing["line1"],
        "tax_region[city]": billing["city"],
    }
    if billing.get("state"):
        body["tax_region[state]"] = billing["state"]

    url = f"{seams.stripe_payment_pages}/{cs_id}"
    try:
        resp = stripe.post(url, data=body, timeout=seams.timeout)
        seams.dump_http(resp, "tax_region_update", body, "POST", url, force=resp.status_code >= 400)
        if resp.status_code < 400:
            seams.log(f"tax_region 已提交: {billing['country']} / {billing['city']} {billing['postal_code']}")
            return True
        if seams.checkout_not_active(resp.text):
            raise RuntimeError("checkout_not_active_session")
        seams.log(f"tax_region 提交失败 HTTP {resp.status_code}: {resp.text[:180]}", "[WARN] ")
    except Exception as exc:
        if seams.checkout_not_active(exc):
            raise
        seams.log(f"tax_region 提交异常: {exc}", "[WARN] ")
    return False
